contracts/interfaces/core/ISBT721.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface ISBT721 {
    /**
     * @dev This emits when a new token is created and bound to an account by
     * any mechanism.
     * Note: For a reliable `to` parameter, retrieve the transaction's
     * authenticated `to` field.
     */
    event Attest(address indexed to, uint256 indexed tokenId);

    /**
     * @dev This emits when an existing SBT is revoked from an account and
     * destroyed by any mechanism.
     * Note: For a reliable `from` parameter, retrieve the transaction's
     * authenticated `from` field.
     */
    event Revoke(address indexed from, uint256 indexed tokenId);

    /**
     * @dev This emits when an existing SBT is burned by an account
     */
    event Burn(address indexed from, uint256 indexed tokenId);

    /**
     * @dev Emitted when `tokenId` token is transferred from `from` to `to`.
     */
    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);

    /**
     * @dev Mints SBT
     *
     * Requirements:
     *
     * - `to` must be valid.
     * - `to` must not exist.
     *
     * Emits a {Attest} event.
     * Emits a {Transfer} event.
     * @return The tokenId of the minted SBT
     */
    function attest(address to) external returns (uint256);

    /**
     * @dev Revokes SBT
     *
     * Requirements:
     *
     * - `from` must exist.
     *
     * Emits a {Revoke} event.
     * Emits a {Transfer} event.
     */
    function revoke(address from) external;

    /**
     * @notice At any time, an SBT receiver must be able to
     *  disassociate themselves from an SBT publicly through calling this
     *  function.
     *
     * Emits a {Burn} event.
     * Emits a {Transfer} event.
     */
    function burn() external;

    /**
     * @notice Count all SBTs assigned to an owner
     * @dev SBTs assigned to the zero address is considered invalid, and this
     * function throws for queries about the zero address.
     * @param owner An address for whom to query the balance
     * @return The number of SBTs owned by `owner`, possibly zero
     */
    function balanceOf(address owner) external view returns (uint256);

    /**
     * @param from The address of the SBT owner
     * @return The tokenId of the owner's SBT, and throw an error if there is no SBT belongs to the given address
     */
    function tokenIdOf(address from) external view returns (uint256);

    /**
     * @notice Find the address bound to a SBT
     * @dev SBTs assigned to zero address are considered invalid, and queries
     *  about them do throw.
     * @param tokenId The identifier for an SBT
     * @return The address of the owner bound to the SBT
     */
    function ownerOf(uint256 tokenId) external view returns (address);

    /**
     * @dev Returns the amount of tokens in existence.
     */
    function totalSupply() external view returns (uint256);
}

contracts/interfaces/core/ITokenAllocato.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

import "../../interfaces/factory/IPoolFactory.sol";

interface ITokenAllocator {
    /// @notice The struct that holds information about allocation
    /// @param isClosed the status of allocation
    /// @param allocator the owner of allocation
    /// @param token the address of token to allocate
    /// @param balance the current allocation balance, that could be claimed by users
    /// @param merkleRoot the Merkle root of tree with users and amounts to claim
    /// @param descriptionURL the ipfs of Merkle tree
    /// @param claimed the set of users, who already claimed in this allocation
    struct AllocationData {
        bool isClosed;
        address allocator;
        address token;
        uint256 balance;
        bytes32 merkleRoot;
        string descriptionURL;
        EnumerableSet.AddressSet claimed;
    }

    /// @notice The struct that returns public information about allocation
    /// @param id the allocation id
    /// @param isClosed the status of allocation
    /// @param allocator the owner of allocation
    /// @param token the address of token to allocate
    /// @param currentBalance the current allocation balance, that could be claimed by users
    /// @param merkleRoot the Merkle root of tree with users and amounts to claim
    /// @param descriptionURL the ipfs of Merkle tree
    struct AllocationInfoView {
        uint256 id;
        bool isClosed;
        address allocator;
        address token;
        uint256 currentBalance;
        bytes32 merkleRoot;
        string descriptionUrl;
    }

    /// @notice The function to get number of allocations (including closed)
    /// @return The id of the last allocation
    function lastAllocationId() external returns (uint256);

    /// @notice The function for injecting dependencies from the Contracts Registry
    /// @param contractsRegistry the address of Contracts Registry
    function setDependencies(address contractsRegistry, bytes memory data_) external;

    /// @notice The function to directly create an allocation
    /// @param token the address of the token to allocate
    /// @param amount the ammount of tokens to allocate
    /// @param merkleRoot the Merkle root of tree with users and amounts to claim
    /// @param descriptionURL the ipfs of Merkle tree
    function createAllocation(
        address token,
        uint256 amount,
        bytes32 merkleRoot,
        string calldata descriptionURL
    ) external;

    /// @notice The function to preallocate tokens and create GovPool
    /// @param merkleRoot the Merkle root of tree with users and amounts to claim
    /// @param descriptionURL the ipfs of Merkle tree
    /// @param parameters the pool deploy parameters
    function allocateAndDeployGovPool(
        bytes32 merkleRoot,
        string calldata descriptionURL,
        IPoolFactory.GovPoolDeployParams calldata parameters
    ) external;

    /// @notice The function to preallocate tokens by request from Pool Factory
    /// @param token the address of the token to allocate
    /// @param amount the ammount of tokens to allocate
    /// @param pool the address of the allocator pool
    /// @param merkleRoot the Merkle root of tree with users and amounts to claim
    /// @param descriptionURL the ipfs of Merkle tree
    function allocateFromFactory(
        address token,
        uint256 amount,
        address pool,
        bytes32 merkleRoot,
        string calldata descriptionURL
    ) external;

    /// @notice The function to close allocation and retrieve remaining balance
    /// @param id the allocation id
    function closeAllocation(uint256 id) external;

    /// @notice The function to claim assets from active allocation
    /// @param id the allocation id
    /// @param amount the exact amount to claim (the one from the Merkle tree)
    /// @param proof the Merkle proof for sender address and correspondent amount
    function claim(uint256 id, uint256 amount, bytes32[] calldata proof) external;

    /// @notice The function to get infromation about the allocation
    /// @param id the allocation id
    /// @return the info about allocation with requested id
    function getAllocationInfo(uint256 id) external view returns (AllocationInfoView memory);

    /// @notice The function to get active allocation infos with defined allocator and token
    /// @param allocator the allocator address
    /// @param token the token address
    /// @return the infos about all active allocations with this allocator and token
    function getAllocations(
        address allocator,
        address token
    ) external view returns (AllocationInfoView[] memory);

    /// @notice The function to get active allocation infos with defined allocator OR token
    /// @param key the token or allocator address (defined with byToken flag)
    /// @param byToken the flag to get info by token (true) or allocator (false)
    /// @return the infos about all active allocations with the desired parameter
    function getAllocationsByTokenOrAllocator(
        address key,
        bool byToken
    ) external view returns (AllocationInfoView[] memory);

    /// @notice The function to find if the user already claimed in the allocation. Doesn't checks closed status
    /// @param id the allocation id
    /// @param user the address of the claimer
    /// @return the claiming status (true if claimed)
    function isClaimed(uint256 id, address user) external view returns (bool);
}

contracts/interfaces/factory/IPoolFactor.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../gov/settings/IGovSettings.sol";
import "../gov/validators/IGovValidators.sol";
import "../gov/proposals/ITokenSaleProposal.sol";
import "../gov/ERC20/IERC20Gov.sol";
import "../core/ICoreProperties.sol";

/**
 * This is the Factory contract for the gov pools. Anyone can create a pool for themselves to become
 * a governance owner (GovPool)
 */
interface IPoolFactory {
    /// @notice The enum that holds information about calculating vote power
    /// @param LINEAR_VOTES the vote power = number of tokens
    /// @param POLYNOMIAL_VOTES the vote power calculated with polynomial formula
    /// @param CUSTOM_VOTES the vote type defined by a customer
    enum VotePowerType {
        LINEAR_VOTES,
        POLYNOMIAL_VOTES,
        CUSTOM_VOTES
    }

    /// @notice General settings of the pool
    /// @param proposalSettings list of infos about settings for proposal types
    /// @param additionalProposalExecutors list of additional proposal executors
    struct SettingsDeployParams {
        IGovSettings.ProposalSettings[] proposalSettings;
        address[] additionalProposalExecutors;
    }

    /// @notice Parameters of validators
    /// @param name the name of a token used by validators
    /// @param symbol the symbol of a token used by validators
    /// @param proposalSettings struct with settings for proposals
    /// @param validators list of the validator addresses
    /// @param balances list of initial token balances of the validators
    struct ValidatorsDeployParams {
        string name;
        string symbol;
        IGovValidators.ProposalSettings proposalSettings;
        address[] validators;
        uint256[] balances;
    }

    /// @notice Parameters of the user keeper
    /// @param tokenAddress address of the tokens used for voting
    /// @param nftAddress address of the NFT used for voting
    /// @param individualPower the voting power of an NFT
    /// @param nftsTotalSupply the NFT collection size
    struct UserKeeperDeployParams {
        address tokenAddress;
        address nftAddress;
        uint256 individualPower;
        uint256 nftsTotalSupply;
    }

    /// @notice The voting power parameters
    /// @param voteType type of algorythm to calculate votes number from token number
    /// @param initData initialization data for standard contract types
    /// @param presetAddress address of custom contract (for custom voteType)
    struct VotePowerDeployParams {
        VotePowerType voteType;
        bytes initData;
        address presetAddress;
    }

    /// @notice The pool deploy parameters
    /// @param settingsParams general settings of the pool
    /// @param validatorsParams parameters of validators
    /// @param userKeeperParams parameters of the user keeper
    /// @param tokenParams the gov token parameters
    /// @param votePowerParams vote power parameters
    /// @param verifier the address of the verifier
    /// @param onlyBABTHolders if true, only KYCed users will be allowed to interact with the pool
    /// @param descriptionURL the description of the pool
    /// @param name the name of the pool
    struct GovPoolDeployParams {
        SettingsDeployParams settingsParams;
        ValidatorsDeployParams validatorsParams;
        UserKeeperDeployParams userKeeperParams;
        IERC20Gov.ConstructorParams tokenParams;
        VotePowerDeployParams votePowerParams;
        address verifier;
        bool onlyBABTHolders;
        string descriptionURL;
        string name;
    }

    /// @notice The predicted pool addresses given tx.origin and GovPool name
    /// @param govPool the predicted govPool address
    /// @param govTokenSale the predicted govTokenSale address
    /// @param govToken the predicted govToken address
    /// @param distributionProposal the predicted distributionProposal address
    /// @param expertNft the predicted expertNft address
    /// @param nftMultiplier the predicted nftMultiplier address
    struct GovPoolPredictedAddresses {
        address govPool;
        address govTokenSale;
        address govToken;
        address distributionProposal;
        address expertNft;
        address nftMultiplier;
    }

    /// @notice This function is used to deploy DAO Pool with TokenSale proposal
    /// @param parameters the pool deploy parameters
    /// @return the deployed pool address
    function deployGovPool(GovPoolDeployParams calldata parameters) external returns (address);

    /// @notice This function is used to clone existent token and deploy DAO Pool with it
    /// @param contractToClone the token address that will be cloned
    /// @param initializeCode the bytecode to initialize token
    /// @param expectedPoolAddress the predicted address of the pool
    /// @param parameters the pool deploy parameters
    /// @param merkleRoot the Merkle root of tree with users and amounts to claim
    /// @param descriptionURL the ipfs of Merkle tree
    /// @param amountToAllocate the amount of tokens to be allocated via Merkle tree
    function createTokenAndDeployPool(
        address contractToClone,
        bytes calldata initializeCode,
        address expectedPoolAddress,
        GovPoolDeployParams calldata parameters,
        bytes32 merkleRoot,
        string calldata descriptionURL,
        uint256 amountToAllocate
    ) external;

    /// @notice The view function that predicts the addresses where
    /// the gov pool proxy, the gov token sale proxy and the gov token will be stored
    /// @param deployer the user that deploys the gov pool (tx.origin)
    /// @param poolName the name of the pool which is part of the salt
    /// @return the predicted addresses
    function predictGovAddresses(
        address deployer,
        string calldata poolName
    ) external view returns (GovPoolPredictedAddresses memory);

    /// @notice The view function that predicts the token address cloned with create2
    /// @param tokenToClone the user that deploys the gov pool (tx.origin)
    /// @param deployer the user that deploys the gov pool (tx.origin)
    /// @param poolName the name of the pool which is part of the salt
    /// @return the predicted address
    function predictTokenAddress(
        address tokenToClone,
        address deployer,
        string calldata poolName
    ) external view returns (address);
}

