// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/math/Math.sol";

import "../../utils/TokenBalance.sol";
import "../../math/MathHelper.sol";

import "../../../gov/GovPool.sol";

library GovPoolCommission {
    using MathHelper for uint256;
    using Math for uint256;
    using TokenBalance for address;

    function payCommission(address rewardToken, uint256 commissionAmount) internal {
        GovPool govPool = GovPool(payable(address(this)));

        (uint256 commissionPercentage, address commissionReceiver) = govPool
            .coreProperties()
            .getDEXECommissionPercentages();

        if (rewardToken == address(0) || commissionReceiver == address(this)) {
            return;
        }

        rewardToken.sendFunds(
            commissionReceiver,
            commissionAmount.percentage(commissionPercentage),
            TokenBalance.TransferType.TryMint
        );
    }
}

contracts/libs/gov/gov-pool/GovPoolCreat.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

import "@solarity/solidity-lib/libs/utils/TypeCaster.sol";

import "../../../interfaces/factory/IPoolRegistry.sol";

import "../../../interfaces/gov/IGovPool.sol";
import "../../../interfaces/gov/proposals/IProposalValidator.sol";
import "../../../interfaces/gov/user-keeper/IGovUserKeeper.sol";
import "../../../interfaces/gov/settings/IGovSettings.sol";
import "../../../interfaces/gov/validators/IGovValidators.sol";
import "../../../interfaces/gov/ERC721/experts/IERC721Expert.sol";

import "../../utils/DataHelper.sol";

import "../../../gov/GovPool.sol";

import "../../../libs/utils/TypeHelper.sol";
import "../../../libs/math/MathHelper.sol";

library GovPoolCreate {
    using EnumerableSet for EnumerableSet.UintSet;
    using DataHelper for bytes;
    using TypeCaster for *;
    using TypeHelper for *;
    using MathHelper for uint256;

    event ProposalCreated(
        uint256 proposalId,
        string proposalDescription,
        IGovPool.ProposalAction[] actionsOnFor,
        IGovPool.ProposalAction[] actionsOnAgainst,
        uint256 quorum,
        uint256 proposalSettings,
        address rewardToken,
        address sender
    );
    event MovedToValidators(uint256 proposalId, address sender);

    function createProposal(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        mapping(address => IGovPool.UserInfo) storage userInfos,
        string calldata _descriptionURL,
        IGovPool.ProposalAction[] calldata actionsOnFor,
        IGovPool.ProposalAction[] calldata actionsOnAgainst
    ) external {
        (IGovSettings.ProposalSettings memory settings, uint256 settingsId) = _validateProposal(
            actionsOnFor,
            actionsOnAgainst
        );

        uint256 proposalId = GovPool(payable(address(this))).latestProposalId();

        uint256 exemptedTreasury = _exemptUserTreasuryFromVoting(
            userInfos,
            actionsOnFor,
            proposalId
        );

        if (exemptedTreasury != 0) {
            settings.quorum = uint128(
                _calculateNewQuorum(uint256(settings.quorum), exemptedTreasury)
            );

            assert(settings.quorum > 0);
        }

        IGovPool.Proposal storage proposal = proposals[proposalId];

        proposal.core = IGovPool.ProposalCore({
            settings: settings,
            voteEnd: uint64(block.timestamp + settings.duration),
            executeAfter: 0,
            executed: false,
            votesFor: 0,
            votesAgainst: 0,
            rawVotesFor: 0,
            rawVotesAgainst: 0,
            givenRewards: 0
        });
        proposal.descriptionURL = _descriptionURL;

        for (uint256 i; i < actionsOnFor.length; i++) {
            proposal.actionsOnFor.push(actionsOnFor[i]);
        }

        for (uint256 i; i < actionsOnAgainst.length; i++) {
            proposal.actionsOnAgainst.push(actionsOnAgainst[i]);
        }

        _canCreate(settings);

        emit ProposalCreated(
            proposalId,
            _descriptionURL,
            actionsOnFor,
            actionsOnAgainst,
            settings.quorum,
            settingsId,
            settings.rewardsInfo.rewardToken,
            msg.sender
        );
    }

    function moveProposalToValidators(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId
    ) external {
        IGovPool.ProposalCore storage core = proposals[proposalId].core;
        (, , address govValidators, , ) = IGovPool(address(this)).getHelperContracts();

        require(
            IGovPool(address(this)).getProposalState(proposalId) ==
                IGovPool.ProposalState.WaitingForVotingTransfer,
            "Gov: can't be moved"
        );

        IGovValidators(govValidators).createExternalProposal(
            proposalId,
            IGovValidators.ProposalSettings(
                core.settings.durationValidators,
                core.settings.executionDelay,
                core.settings.quorumValidators
            )
        );

        emit MovedToValidators(proposalId, msg.sender);
    }

    function _validateProposal(
        IGovPool.ProposalAction[] calldata actionsFor,
        IGovPool.ProposalAction[] calldata actionsAgainst
    ) internal view returns (IGovSettings.ProposalSettings memory settings, uint256 settingsId) {
        require(actionsFor.length != 0, "Gov: invalid array length");

        address mainExecutor = actionsFor[actionsFor.length - 1].executor;

        _validateProposalCreation(mainExecutor, actionsFor);

        (address govSettingsAddress, , , , ) = IGovPool(address(this)).getHelperContracts();
        IGovSettings govSettings = IGovSettings(govSettingsAddress);

        settingsId = govSettings.executorToSettings(mainExecutor);

        bool forceDefaultSettings = _handleDataForProposal(settingsId, govSettings, actionsFor);

        if (actionsAgainst.length != 0) {
            _validateMetaGovernance(actionsFor, actionsAgainst);
        }

        if (forceDefaultSettings) {
            settingsId = uint256(IGovSettings.ExecutorType.DEFAULT);
            settings = govSettings.getDefaultSettings();
        } else {
            settings = govSettings.getExecutorSettings(mainExecutor);
        }
    }

    function _exemptUserTreasuryFromVoting(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        IGovPool.ProposalAction[] calldata actions,
        uint256 proposalId
    ) internal returns (uint256 exemptedTreasury) {
        IGovPool govPool = IGovPool(address(this));

        (, address userKeeperAddress, , , ) = govPool.getHelperContracts();
        (, address expertNft, address dexeExpertNft, ) = govPool.getNftContracts();

        IGovUserKeeper userKeeper = IGovUserKeeper(userKeeperAddress);

        for (uint256 i; i < actions.length; i++) {
            IGovPool.ProposalAction calldata action = actions[i];
            bytes4 selector = action.data.getSelector();
            address user;

            if (
                (action.executor == expertNft || action.executor == dexeExpertNft) &&
                selector == IERC721Expert.burn.selector
            ) {
                user = abi.decode(action.data[4:], (address));
            } else if (
                action.executor == address(this) &&
                (selector == IGovPool.delegateTreasury.selector ||
                    selector == IGovPool.undelegateTreasury.selector)
            ) {
                user = abi.decode(action.data[4:36], (address));
            } else {
                continue;
            }

            if (userInfos[user].treasuryExemptProposals.add(proposalId)) {
                exemptedTreasury += userKeeper
                .votingPower(
                    user.asSingletonArray(),
                    IGovPool.VoteType.TreasuryVote.asSingletonArray(),
                    false
                )[0].rawPower;
            }
        }
    }

    function _validateProposalCreation(
        address executor,
        IGovPool.ProposalAction[] calldata actionsFor
    ) internal view {
        (bool ok, bytes memory data) = executor.staticcall{gas: 30000}(
            abi.encodeWithSelector(IProposalValidator.validate.selector, actionsFor)
        );

        require(!ok || data.length == 0 || abi.decode(data, (bool)), "Gov: validation failed");
    }

    function _canCreate(IGovSettings.ProposalSettings memory settings) internal view {
        IGovPool govPool = IGovPool(address(this));

        (, , address dexeExpertNft, ) = govPool.getNftContracts();

        if (IERC721Expert(dexeExpertNft).isExpert(msg.sender)) {
            return;
        }

        (, address userKeeper, , , ) = govPool.getHelperContracts();

        require(
            IGovUserKeeper(userKeeper).canCreate(
                msg.sender,
                settings.delegatedVotingAllowed
                    ? IGovPool.VoteType.DelegatedVote
                    : IGovPool.VoteType.PersonalVote,
                settings.minVotesForCreating
            ),
            "Gov: low creating power"
        );
    }

    function _handleDataForInternalProposal(
        IGovSettings govSettings,
        IGovPool.ProposalAction[] calldata actions
    ) internal view {
        for (uint256 i; i < actions.length; i++) {
            bytes4 selector = actions[i].data.getSelector();
            uint256 executorSettings = govSettings.executorToSettings(actions[i].executor);

            if (actions[i].value != 0) {
                require(
                    executorSettings == uint256(IGovSettings.ExecutorType.INTERNAL) &&
                        selector == IGovPool.delegateTreasury.selector,
                    "Gov: invalid internal data"
                );
            } else {
                require(
                    executorSettings == uint256(IGovSettings.ExecutorType.INTERNAL) &&
                        (selector == IGovSettings.addSettings.selector ||
                            selector == IGovSettings.editSettings.selector ||
                            selector == IGovSettings.changeExecutors.selector ||
                            selector == IGovUserKeeper.setERC20Address.selector ||
                            selector == IGovUserKeeper.setERC721Address.selector ||
                            selector == IGovPool.changeVotePower.selector ||
                            selector == IGovPool.editDescriptionURL.selector ||
                            selector == IGovPool.setNftMultiplierAddress.selector ||
                            selector == IGovPool.changeVerifier.selector ||
                            selector == IGovPool.delegateTreasury.selector ||
                            selector == IGovPool.undelegateTreasury.selector ||
                            selector == IGovPool.changeBABTRestriction.selector ||
                            selector == IGovPool.setCreditInfo.selector),
                    "Gov: invalid internal data"
                );
            }
        }
    }

    function _handleDataForProposal(
        uint256 settingsId,
        IGovSettings govSettings,
        IGovPool.ProposalAction[] calldata actions
    ) internal view returns (bool) {
        if (settingsId == uint256(IGovSettings.ExecutorType.INTERNAL)) {
            _handleDataForInternalProposal(govSettings, actions);
            return false;
        }

        if (settingsId == uint256(IGovSettings.ExecutorType.VALIDATORS)) {
            _handleDataForValidatorBalanceProposal(actions);
            return false;
        }

        if (settingsId == uint256(IGovSettings.ExecutorType.DEFAULT)) {
            return false;
        }

        return _handleDataForExistingSettingsProposal(govSettings, settingsId, actions);
    }

    function _handleDataForExistingSettingsProposal(
        IGovSettings govSettings,
        uint256 lastSettings,
        IGovPool.ProposalAction[] calldata actions
    ) internal view returns (bool) {
        for (uint256 i; i < actions.length - 1; i++) {
            bytes4 selector = actions[i].data.getSelector();

            if (
                govSettings.executorToSettings(actions[i].executor) != lastSettings &&
                (actions[i].value != 0 ||
                    (selector != IERC20.approve.selector && // same as selector != IERC721.approve.selector
                        selector != IERC721.setApprovalForAll.selector)) // same as IERC1155.setApprovalForAll.selector
            ) {
                return true; // should use default settings
            }
        }

        return false;
    }

    function _calculateNewQuorum(
        uint256 quorum,
        uint256 exemptedTreasury
    ) internal view returns (uint256) {
        (, address userKeeper, , , ) = IGovPool(address(this)).getHelperContracts();

        uint256 totalVoteWeight = IGovUserKeeper(userKeeper).getTotalPower();
        uint256 newTotalVoteWeight = (totalVoteWeight - exemptedTreasury).percentage(quorum);

        return PERCENTAGE_100.ratio(newTotalVoteWeight, totalVoteWeight);
    }

    function _validateMetaGovernance(
        IGovPool.ProposalAction[] calldata actionsFor,
        IGovPool.ProposalAction[] calldata actionsAgainst
    ) internal view {
        require(actionsFor.length == actionsAgainst.length, "Gov: invalid actions length");

        address metaGovPool = _validateVote(
            actionsFor[actionsFor.length - 1],
            actionsAgainst[actionsAgainst.length - 1]
        );

        for (uint256 i; i < actionsFor.length - 1; i++) {
            _validateApproveOrDeposit(actionsFor[i], actionsAgainst[i], metaGovPool);
        }
    }

    function _validateVote(
        IGovPool.ProposalAction calldata actionFor,
        IGovPool.ProposalAction calldata actionAgainst
    ) internal view returns (address metaGovPool) {
        (, , , address poolRegistryAddress, ) = IGovPool(address(this)).getHelperContracts();

        metaGovPool = actionFor.executor;

        require(metaGovPool == actionAgainst.executor, "Gov: invalid executor");
        require(
            IPoolRegistry(poolRegistryAddress).isGovPool(metaGovPool),
            "Gov: invalid executor"
        );

        bytes4 selector = actionFor.data.getSelector();

        require(
            selector == IGovPool.vote.selector && selector == actionAgainst.data.getSelector(),
            "Gov: invalid selector"
        );

        (
            uint256 proposalIdFor,
            bool isVoteForFor,
            uint256 voteAmountFor,
            uint256[] memory voteNftsFor
        ) = _decodeVoteFunction(actionFor);
        (
            uint256 proposalIdAgainst,
            bool isVoteForAgainst,
            uint256 voteAmountAgainst,
            uint256[] memory voteNftsAgainst
        ) = _decodeVoteFunction(actionAgainst);

        require(proposalIdFor == proposalIdAgainst, "Gov: invalid proposal id");
        require(isVoteForFor && !isVoteForAgainst, "Gov: invalid vote");
        require(voteAmountFor == voteAmountAgainst, "Gov: invalid vote amount");
        require(voteNftsFor.length == voteNftsAgainst.length, "Gov: invalid nfts length");

        for (uint256 i = 0; i < voteNftsFor.length; i++) {
            require(voteNftsFor[i] == voteNftsAgainst[i], "Gov: invalid nft vote");
        }
    }

    function _validateApproveOrDeposit(
        IGovPool.ProposalAction calldata actionFor,
        IGovPool.ProposalAction calldata actionAgainst,
        address metaGovPool
    ) internal view {
        (, address metaUserKeeper, , , ) = IGovPool(metaGovPool).getHelperContracts();

        require(actionFor.executor == actionAgainst.executor, "Gov: invalid executor");

        bytes4 selector = actionFor.data.getSelector();

        require(selector == actionAgainst.data.getSelector(), "Gov: invalid selector");

        if (selector == IERC20.approve.selector) {
            _validateApprove(actionFor, actionAgainst, metaUserKeeper);
        } else if (selector == IERC721.setApprovalForAll.selector) {
            _validateSetApprovalForAll(actionFor, actionAgainst, metaUserKeeper);
        } else if (selector == IGovPool.deposit.selector) {
            _validateDeposit(actionFor, actionAgainst, metaGovPool);
        } else {
            revert("Gov: selector not supported");
        }
    }

    function _validateApprove(
        IGovPool.ProposalAction calldata actionFor,
        IGovPool.ProposalAction calldata actionAgainst,
        address metaUserKeeper
    ) internal view {
        address metaToken = IGovUserKeeper(metaUserKeeper).tokenAddress();
        address metaNft = IGovUserKeeper(metaUserKeeper).nftAddress();

        require(
            actionFor.executor == metaToken || actionFor.executor == metaNft,
            "Gov: invalid executor"
        );

        (address spenderFor, uint256 amountFor) = _decodeApproveFunction(actionFor);
        (address spenderAgainst, uint256 amountAgainst) = _decodeApproveFunction(actionAgainst);

        require(
            spenderFor == metaUserKeeper && spenderFor == spenderAgainst,
            "Gov: invalid spender"
        );
        require(amountFor == amountAgainst, "Gov: invalid amount");
    }

    function _validateSetApprovalForAll(
        IGovPool.ProposalAction calldata actionFor,
        IGovPool.ProposalAction calldata actionAgainst,
        address metaUserKeeper
    ) internal view {
        address metaNft = IGovUserKeeper(metaUserKeeper).nftAddress();

        require(actionFor.executor == metaNft, "Gov: invalid executor");

        (address operatorFor, bool approvedFor) = _decodeSetApprovalForAllFunction(actionFor);
        (address operatorAgainst, bool approvedAgainst) = _decodeSetApprovalForAllFunction(
            actionAgainst
        );

        require(
            operatorFor == metaUserKeeper && operatorFor == operatorAgainst,
            "Gov: invalid operator"
        );
        require(approvedFor == approvedAgainst, "Gov: invalid approve");
    }

    function _validateDeposit(
        IGovPool.ProposalAction calldata actionFor,
        IGovPool.ProposalAction calldata actionAgainst,
        address metaGovPool
    ) internal pure {
        (uint256 amountFor, uint256[] memory nftIdsFor) = _decodeDepositFunction(actionFor);
        (uint256 amountAgainst, uint256[] memory nftIdsAgainst) = _decodeDepositFunction(
            actionAgainst
        );

        require(actionFor.executor == metaGovPool, "Gov: invalid executor");
        require(amountFor == amountAgainst, "Gov: invalid amount");
        require(actionFor.value == actionAgainst.value, "Gov: invalid value");
        require(nftIdsFor.length == nftIdsAgainst.length, "Gov: invalid nfts length");

        for (uint256 i = 0; i < nftIdsFor.length; i++) {
            require(nftIdsFor[i] == nftIdsAgainst[i], "Gov: invalid nft deposit");
        }
    }

    function _handleDataForValidatorBalanceProposal(
        IGovPool.ProposalAction[] calldata actions
    ) internal pure {
        require(actions.length == 1, "Gov: invalid executors length");

        for (uint256 i; i < actions.length; i++) {
            bytes4 selector = actions[i].data.getSelector();

            require(
                actions[i].value == 0 && (selector == IGovValidators.changeBalances.selector),
                "Gov: invalid internal data"
            );
        }
    }

    function _decodeVoteFunction(
        IGovPool.ProposalAction calldata action
    )
        internal
        pure
        returns (
            uint256 proposalId,
            bool isVoteFor,
            uint256 voteAmount,
            uint256[] memory voteNftIds
        )
    {
        (proposalId, isVoteFor, voteAmount, voteNftIds) = abi.decode(
            action.data[4:],
            (uint256, bool, uint256, uint256[])
        );
    }

    function _decodeDepositFunction(
        IGovPool.ProposalAction calldata action
    ) internal pure returns (uint256 amount, uint256[] memory nftIds) {
        (amount, nftIds) = abi.decode(action.data[4:], (uint256, uint256[]));
    }

    function _decodeApproveFunction(
        IGovPool.ProposalAction calldata action
    ) internal pure returns (address spender, uint256 amount) {
        (spender, amount) = abi.decode(action.data[4:], (address, uint256));
    }

    function _decodeSetApprovalForAllFunction(
        IGovPool.ProposalAction calldata action
    ) internal pure returns (address operator, bool approved) {
        (operator, approved) = abi.decode(action.data[4:], (address, bool));
    }
}

contracts/libs/gov/gov-pool/GovPoolCredi.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "@solarity/solidity-lib/libs/arrays/ArrayHelper.sol";
import "@solarity/solidity-lib/libs/utils/DecimalsConverter.sol";

import "../../../interfaces/gov/IGovPool.sol";

import "../../../libs/utils/TokenBalance.sol";

library GovPoolCredit {
    using SafeERC20 for IERC20;
    using ArrayHelper for uint256[];
    using DecimalsConverter for *;
    using TokenBalance for address;

    function setCreditInfo(
        IGovPool.CreditInfo storage creditInfo,
        address[] calldata tokens,
        uint256[] calldata amounts
    ) external {
        require(
            tokens.length == amounts.length,
            "GPC: Number of tokens and amounts are not equal"
        );

        uint256 length = creditInfo.tokenList.length;

        for (uint256 i = 0; i < length; i++) {
            delete creditInfo.tokenInfo[creditInfo.tokenList[i]].monthLimit;
        }

        creditInfo.tokenList = tokens;

        for (uint256 i = 0; i < tokens.length; i++) {
            address currentToken = tokens[i];
            require(currentToken != address(0), "GPC: Token address could not be zero");

            creditInfo.tokenInfo[currentToken].monthLimit = amounts[i];
        }
    }

    function transferCreditAmount(
        IGovPool.CreditInfo storage creditInfo,
        address[] calldata tokens,
        uint256[] calldata amounts,
        address destination
    ) external {
        uint256 tokensLength = tokens.length;
        require(amounts.length == tokensLength, "GPC: Number of tokens and amounts are not equal");

        for (uint256 i = 0; i < tokensLength; i++) {
            address currentToken = tokens[i];
            uint256 currentAmount = amounts[i];
            uint256 tokenCredit = _getCreditBalanceForToken(creditInfo, currentToken);

            require(
                currentAmount <= tokenCredit,
                "GPC: Current credit permission < amount to withdraw"
            );

            creditInfo.tokenInfo[currentToken].timestamps.push(block.timestamp);
            uint256[] storage history = creditInfo.tokenInfo[currentToken].cumulativeAmounts;

            history.push(currentAmount + (history.length == 0 ? 0 : history[history.length - 1]));

            currentToken.sendFunds(destination, currentAmount);
        }
    }

    function getCreditInfo(
        IGovPool.CreditInfo storage creditInfo
    ) external view returns (IGovPool.CreditInfoView[] memory info) {
        uint256 infoLength = creditInfo.tokenList.length;
        info = new IGovPool.CreditInfoView[](infoLength);

        mapping(address => IGovPool.TokenCreditInfo) storage tokenInfo = creditInfo.tokenInfo;

        for (uint256 i = 0; i < infoLength; i++) {
            address currentToken = creditInfo.tokenList[i];
            uint256 monthLimit = tokenInfo[currentToken].monthLimit;

            info[i] = IGovPool.CreditInfoView({
                token: currentToken,
                monthLimit: monthLimit,
                currentWithdrawLimit: _getCreditBalanceForToken(creditInfo, currentToken)
            });
        }
    }

    function _getCreditBalanceForToken(
        IGovPool.CreditInfo storage creditInfo,
        address token
    ) internal view returns (uint256) {
        IGovPool.TokenCreditInfo storage tokenInfo = creditInfo.tokenInfo[token];
        uint256[] storage amounts = tokenInfo.cumulativeAmounts;
        uint256 historyLength = amounts.length;

        uint256 index = tokenInfo.timestamps.upperBound(_monthAgo());
        uint256 amountWithdrawn;

        if (index == historyLength) {
            return tokenInfo.monthLimit;
        }

        amountWithdrawn = amounts[historyLength - 1] - (index == 0 ? 0 : amounts[index - 1]);

        return
            amountWithdrawn >= tokenInfo.monthLimit ? 0 : tokenInfo.monthLimit - amountWithdrawn;
    }

    function _monthAgo() private view returns (uint256) {
        return block.timestamp - 30 days;
    }
}

contracts/libs/gov/gov-pool/GovPoolExecu.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/math/Math.sol";

import "../../../interfaces/gov/IGovPool.sol";
import "../../../interfaces/gov/settings/IGovSettings.sol";
import "../../../interfaces/gov/validators/IGovValidators.sol";

import "../../utils/DataHelper.sol";
import "../../math/MathHelper.sol";
import "../../utils/TokenBalance.sol";
import "./GovPoolCommission.sol";

import "../../../gov/GovPool.sol";

library GovPoolExecute {
    using DataHelper for bytes;
    using MathHelper for uint256;
    using Math for uint256;
    using TokenBalance for address;
    using GovPoolCommission for address;

    event ProposalExecuted(uint256 proposalId, bool isFor, address sender);

    function execute(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId
    ) external {
        IGovPool.Proposal storage proposal = proposals[proposalId];
        IGovPool.ProposalCore storage core = proposal.core;

        GovPool govPool = GovPool(payable(address(this)));

        IGovPool.ProposalState proposalState = govPool.getProposalState(proposalId);

        require(
            proposalState == IGovPool.ProposalState.SucceededFor ||
                proposalState == IGovPool.ProposalState.SucceededAgainst,
            "Gov: invalid status"
        );

        core.executed = true;

        (, , address govValidatorsAddress, , ) = GovPool(payable(address(this)))
            .getHelperContracts();
        IGovValidators govValidators = IGovValidators(govValidatorsAddress);

        bool validatorsVotingSucceeded = govValidators.getProposalState(proposalId, false) ==
            IGovValidators.ProposalState.Succeeded;

        if (validatorsVotingSucceeded) {
            govValidators.executeExternalProposal(proposalId);
        }

        IGovPool.ProposalAction[] storage actions = _proposalActionsResult(proposal);

        uint256 actionsLength = actions.length;

        for (uint256 i; i < actionsLength; i++) {
            (bool status, bytes memory returnedData) = actions[i].executor.call{
                value: actions[i].value
            }(actions[i].data);

            if (!status) {
                revert(returnedData.getRevertMsg());
            }
        }

        emit ProposalExecuted(
            proposalId,
            proposalState == IGovPool.ProposalState.SucceededFor,
            msg.sender
        );

        core.settings.rewardsInfo.rewardToken.payCommission(_getCommission(core));
    }

    function tryExecute(IGovPool.ProposalAction[] calldata actions) external {
        uint256 length = actions.length;

        for (uint256 i = 0; i < length; i++) {
            (bool success, ) = actions[i].executor.call{value: actions[i].value}(actions[i].data);

            if (!success) {
                _throwRevert(false);
            }
        }

        _throwRevert(true);
    }

    function _proposalActionsResult(
        IGovPool.Proposal storage proposal
    ) internal view returns (IGovPool.ProposalAction[] storage) {
        IGovPool.ProposalCore storage core = proposal.core;

        return
            core.votesFor > core.votesAgainst ? proposal.actionsOnFor : proposal.actionsOnAgainst;
    }

    function _getCommission(IGovPool.ProposalCore storage core) internal view returns (uint256) {
        return
            core.givenRewards +
            (core.rawVotesFor + core.rawVotesAgainst).ratio(
                core.settings.rewardsInfo.voteRewardsCoefficient,
                (PRECISION * 100)
            );
    }

    function _throwRevert(bool success) internal pure {
        assembly {
            mstore(0, success)
            revert(0, 32)
        }
    }
}

contracts/libs/gov/gov-pool/GovPoolMicro.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/math/Math.sol";

import "@solarity/solidity-lib/libs/arrays/ArrayHelper.sol";

import "./GovPoolRewards.sol";

import "../../utils/TokenBalance.sol";
import "../../math/MathHelper.sol";

import "../../../interfaces/gov/IGovPool.sol";
import "../../../interfaces/gov/user-keeper/IGovUserKeeper.sol";

library GovPoolMicropool {
    using TokenBalance for address;
    using Math for uint256;
    using MathHelper for uint256;
    using ArrayHelper for uint256[];
    using GovPoolRewards for *;

    event DelegatorRewardsClaimed(
        uint256 proposalId,
        address delegator,
        address delegatee,
        address token,
        uint256 amount
    );

    function saveDelegationInfo(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        address delegatee
    ) external {
        (, address userKeeper, , , ) = IGovPool(address(this)).getHelperContracts();

        IGovPool.DelegatorInfo storage delegatorInfo = userInfos[delegatee].delegatorInfos[
            msg.sender
        ];

        uint256[] storage delegationTimes = delegatorInfo.delegationTimes;
        uint256[] storage delegationPowers = delegatorInfo.delegationPowers;

        uint256 length = delegationTimes.length;

        if (length > 0 && delegationTimes[length - 1] == block.timestamp) {
            delegationTimes.pop();
            delegationPowers.pop();
        }

        delegationTimes.push(block.timestamp);
        delegationPowers.push(
            IGovUserKeeper(userKeeper).getDelegatedAssetsPower(msg.sender, delegatee)
        );
    }

    function claim(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId,
        address delegator,
        address delegatee
    ) external {
        uint256 reward = _getExpectedRewards(
            userInfos,
            proposals,
            proposalId,
            delegator,
            delegatee
        );

        require(reward != 0, "Gov: no micropool rewards");

        IGovPool.DelegatorInfo storage delegatorInfo = userInfos[delegatee].delegatorInfos[
            delegator
        ];

        delegatorInfo.isClaimed[proposalId] = true;

        address rewardToken = proposals[proposalId].core.settings.rewardsInfo.rewardToken;

        uint256 paid = rewardToken.sendFunds(delegator, reward, TokenBalance.TransferType.TryMint);

        if (paid < reward) {
            delegatorInfo.isClaimed[proposalId] = false;
            delegatorInfo.partiallyClaimed[proposalId] += paid;
        }

        emit DelegatorRewardsClaimed(proposalId, delegator, delegatee, rewardToken, paid);
    }

    function getDelegatorRewards(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256[] calldata proposalIds,
        address delegator,
        address delegatee
    ) external view returns (IGovPool.DelegatorRewards memory rewards) {
        rewards.expectedRewards = new uint256[](proposalIds.length);
        rewards.rewardTokens = new address[](proposalIds.length);
        rewards.isVoteFor = new bool[](proposalIds.length);
        rewards.isClaimed = new bool[](proposalIds.length);

        IGovPool.UserInfo storage userInfo = userInfos[delegatee];

        for (uint256 i; i < proposalIds.length; i++) {
            uint256 proposalId = proposalIds[i];

            IGovPool.Proposal storage proposal = proposals[proposalId];

            if (!proposal.core.executed) {
                continue;
            }

            rewards.expectedRewards[i] = _getExpectedRewards(
                userInfos,
                proposals,
                proposalId,
                delegator,
                delegatee
            );
            rewards.rewardTokens[i] = proposal.core.settings.rewardsInfo.rewardToken;
            rewards.isVoteFor[i] = userInfo.voteInfos[proposalId].isVoteFor;
            rewards.isClaimed[i] = userInfo.delegatorInfos[delegator].isClaimed[proposalId];
        }
    }

    function _getExpectedRewards(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId,
        address delegator,
        address delegatee
    ) private view returns (uint256) {
        IGovPool.ProposalCore storage core = proposals[proposalId].core;
        IGovPool.UserInfo storage userInfo = userInfos[delegatee];
        IGovPool.RawVote storage micropoolRawVote = userInfo.voteInfos[proposalId].rawVotes[
            IGovPool.VoteType.MicropoolVote
        ];
        IGovPool.DelegatorInfo storage delegatorInfo = userInfo.delegatorInfos[delegator];

        (, uint256 delegatorsRewards) = core._getVotingRewards(userInfos, proposalId, delegatee);

        if (!core.executed || delegatorInfo.isClaimed[proposalId] || delegatorsRewards == 0) {
            return 0;
        }

        uint256[] storage timestamps = delegatorInfo.delegationTimes;

        uint256 quorumReachedTime = core.executeAfter - core.settings.executionDelay;
        uint256 index = timestamps.lowerBound(quorumReachedTime);

        if (index == 0) {
            return 0;
        }

        if (index == timestamps.length || timestamps[index] != quorumReachedTime) {
            --index;
        }

        uint256 totalVoted = micropoolRawVote.totalVoted;

        uint256 reward = delegatorsRewards.ratio(
            delegatorInfo.delegationPowers[index],
            totalVoted
        );

        return reward - delegatorInfo.partiallyClaimed[proposalId];
    }
}

contracts/libs/gov/gov-pool/GovPoolOffch.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import "../../../interfaces/gov/IGovPool.sol";

import "./GovPoolCommission.sol";

import "../../../gov/GovPool.sol";

library GovPoolOffchain {
    using ECDSA for bytes32;
    using GovPoolCommission for address;

    event OffchainResultsSaved(string resultsHash, address sender);

    function saveOffchainResults(
        IGovPool.OffChain storage offChain,
        string calldata resultsHash,
        bytes calldata signature
    ) external {
        bytes32 signHash_ = getSignHash(resultsHash, msg.sender);

        require(!offChain.usedHashes[signHash_], "Gov: already used");
        require(
            signHash_.toEthSignedMessageHash().recover(signature) == offChain.verifier,
            "Gov: invalid signer"
        );

        offChain.resultsHash = resultsHash;
        offChain.usedHashes[signHash_] = true;

        _payCommission();

        emit OffchainResultsSaved(resultsHash, msg.sender);
    }

    function getSignHash(string calldata resultsHash, address user) public view returns (bytes32) {
        return keccak256(abi.encodePacked(resultsHash, user, block.chainid, address(this)));
    }

    function _payCommission() internal {
        (address settingsAddress, , , , ) = GovPool(payable(address(this))).getHelperContracts();

        IGovSettings.ProposalSettings memory internalSettings = IGovSettings(settingsAddress)
            .getInternalSettings();

        internalSettings.rewardsInfo.rewardToken.payCommission(
            internalSettings.rewardsInfo.executionReward
        );
    }
}

contracts/libs/gov/gov-pool/GovPoolRewar.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

import "../../../interfaces/core/ICoreProperties.sol";

import "../../../interfaces/gov/IGovPool.sol";
import "../../../interfaces/gov/ERC721/multipliers/IAbstractERC721Multiplier.sol";

import "../../utils/TokenBalance.sol";
import "../../math/MathHelper.sol";

library GovPoolRewards {
    using EnumerableSet for EnumerableSet.AddressSet;
    using TokenBalance for address;
    using MathHelper for uint256;
    using Math for uint256;

    event RewardClaimed(uint256 proposalId, address sender, address token, uint256 rewards);
    event VotingRewardClaimed(
        uint256 proposalId,
        address sender,
        address token,
        IGovPool.VotingRewards rewards
    );

    function updateStaticRewards(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId,
        address user,
        IGovPool.RewardType rewardType
    ) external {
        IGovPool.ProposalCore storage core = proposals[proposalId].core;
        IGovSettings.RewardsInfo storage rewardsInfo = core.settings.rewardsInfo;

        uint256 amountToAdd = rewardType == IGovPool.RewardType.Create
            ? rewardsInfo.creationReward
            : rewardsInfo.executionReward;

        userInfos[user].pendingRewards.staticRewards[proposalId] += amountToAdd;

        core.givenRewards += amountToAdd;
    }

    function updateOffchainRewards(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        address user
    ) external {
        (address govSettings, , , , ) = IGovPool(address(this)).getHelperContracts();

        IGovSettings.RewardsInfo memory rewardsInfo = IGovSettings(govSettings)
            .getInternalSettings()
            .rewardsInfo;

        address rewardToken = rewardsInfo.rewardToken;

        IGovPool.PendingRewards storage userRewards = userInfos[user].pendingRewards;

        userRewards.offchainRewards[rewardToken] += rewardsInfo.executionReward;
        userRewards.offchainTokens.add(rewardToken);
    }

    function updateVotingRewards(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId,
        address user
    ) external {
        IGovPool.ProposalCore storage core = proposals[proposalId].core;
        IGovPool.PendingRewards storage userRewards = userInfos[user].pendingRewards;

        if (userRewards.areVotingRewardsSet[proposalId]) {
            return;
        }

        (IGovPool.VotingRewards memory votingRewards, ) = _getVotingRewards(
            core,
            userInfos,
            proposalId,
            user
        );

        if (votingRewards.personal + votingRewards.micropool + votingRewards.treasury == 0) {
            return;
        }

        userRewards.votingRewards[proposalId] = votingRewards;
        userRewards.areVotingRewardsSet[proposalId] = true;
    }

    function claimReward(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId,
        address user
    ) external {
        IGovPool.PendingRewards storage userRewards = userInfos[user].pendingRewards;

        if (proposalId != 0) {
            IGovPool.ProposalCore storage core = proposals[proposalId].core;

            require(core.executed, "Gov: proposal is not executed");

            uint256 staticRewardsToPay = userRewards.staticRewards[proposalId];
            uint256 staticRewardsPaid;

            IGovPool.VotingRewards memory votingRewardsToPay = userRewards.votingRewards[
                proposalId
            ];
            IGovPool.VotingRewards memory votingRewardsPaid;

            delete userRewards.staticRewards[proposalId];
            delete userRewards.votingRewards[proposalId];

            address rewardToken = core.settings.rewardsInfo.rewardToken;

            uint256 rewardsPaid = _sendRewards(
                user,
                core.settings.rewardsInfo.rewardToken,
                staticRewardsToPay +
                    votingRewardsToPay.personal +
                    votingRewardsToPay.micropool +
                    votingRewardsToPay.treasury
            );

            (staticRewardsToPay, staticRewardsPaid) = _recalculateAllRewards(
                rewardsPaid,
                staticRewardsToPay,
                votingRewardsPaid,
                votingRewardsToPay
            );

            userRewards.staticRewards[proposalId] = staticRewardsToPay;
            userRewards.votingRewards[proposalId] = votingRewardsToPay;

            emit RewardClaimed(proposalId, user, rewardToken, staticRewardsPaid);
            emit VotingRewardClaimed(proposalId, user, rewardToken, votingRewardsPaid);
        } else {
            EnumerableSet.AddressSet storage offchainTokens = userRewards.offchainTokens;
            mapping(address => uint256) storage offchainRewards = userRewards.offchainRewards;

            uint256 length = offchainTokens.length();

            for (uint256 i = length; i > 0; i--) {
                address rewardToken = offchainTokens.at(i - 1);
                uint256 rewards = offchainRewards[rewardToken];

                delete offchainRewards[rewardToken];

                uint256 paid = _sendRewards(user, rewardToken, rewards);

                if (paid < rewards) {
                    offchainRewards[rewardToken] = rewards - paid;
                } else {
                    offchainTokens.remove(rewardToken);
                }

                emit RewardClaimed(0, user, rewardToken, paid);
            }
        }
    }

    function getPendingRewards(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        address user,
        uint256[] calldata proposalIds
    ) external view returns (IGovPool.PendingRewardsView memory rewards) {
        IGovPool.PendingRewards storage userRewards = userInfos[user].pendingRewards;

        uint256 tokensLength = userRewards.offchainTokens.length();

        rewards.onchainTokens = new address[](proposalIds.length);
        rewards.staticRewards = new uint256[](proposalIds.length);
        rewards.votingRewards = new IGovPool.VotingRewards[](proposalIds.length);
        rewards.offchainRewards = new uint256[](tokensLength);
        rewards.offchainTokens = new address[](tokensLength);

        for (uint256 i = 0; i < proposalIds.length; i++) {
            uint256 proposalId = proposalIds[i];

            IGovPool.ProposalCore storage core = proposals[proposalId].core;

            if (!core.executed) {
                continue;
            }

            rewards.onchainTokens[i] = core.settings.rewardsInfo.rewardToken;
            rewards.staticRewards[i] = userRewards.staticRewards[proposalId];

            if (!userRewards.areVotingRewardsSet[proposalId]) {
                (rewards.votingRewards[i], ) = _getVotingRewards(
                    core,
                    userInfos,
                    proposalId,
                    user
                );
            } else {
                rewards.votingRewards[i] = userRewards.votingRewards[proposalId];
            }
        }

        for (uint256 i = 0; i < rewards.offchainTokens.length; i++) {
            address token = userRewards.offchainTokens.at(i);

            rewards.offchainTokens[i] = token;
            rewards.offchainRewards[i] = userRewards.offchainRewards[token];
        }
    }

    function _sendRewards(
        address receiver,
        address rewardToken,
        uint256 rewards
    ) internal returns (uint256) {
        require(rewardToken != address(0), "Gov: rewards are off");
        require(rewards != 0, "Gov: zero rewards");

        return rewardToken.sendFunds(receiver, rewards, TokenBalance.TransferType.TryMint);
    }

    function _getMultipliedRewards(address user, uint256 amount) internal view returns (uint256) {
        (address nftMultiplier, , , ) = IGovPool(address(this)).getNftContracts();

        if (nftMultiplier != address(0)) {
            amount += IAbstractERC721Multiplier(nftMultiplier).getExtraRewards(user, amount);
        }

        return amount;
    }

    function _getVotingRewards(
        IGovPool.ProposalCore storage core,
        mapping(address => IGovPool.UserInfo) storage userInfos,
        uint256 proposalId,
        address user
    )
        internal
        view
        returns (IGovPool.VotingRewards memory votingRewards, uint256 delegatorsRewards)
    {
        IGovPool.VoteInfo storage voteInfo = userInfos[user].voteInfos[proposalId];

        IGovPool.ProposalState executedState = voteInfo.isVoteFor
            ? IGovPool.ProposalState.ExecutedFor
            : IGovPool.ProposalState.ExecutedAgainst;

        if (
            IGovPool(address(this)).getProposalState(proposalId) != executedState ||
            voteInfo.totalRawVoted == 0
        ) {
            return (votingRewards, 0);
        }

        return _splitVotingRewards(voteInfo, user, _getInitialVotingRewards(core, voteInfo));
    }

    function _getInitialVotingRewards(
        IGovPool.ProposalCore storage core,
        IGovPool.VoteInfo storage voteInfo
    ) internal view returns (uint256) {
        (uint256 coreVotes, uint256 coreRawVotes) = voteInfo.isVoteFor
            ? (core.votesFor, core.rawVotesFor)
            : (core.votesAgainst, core.rawVotesAgainst);

        return
            coreRawVotes
                .ratio(core.settings.rewardsInfo.voteRewardsCoefficient, (PRECISION * 100))
                .ratio(voteInfo.totalVoted, coreVotes);
    }

    function _splitVotingRewards(
        IGovPool.VoteInfo storage voteInfo,
        address user,
        uint256 totalRewards
    )
        internal
        view
        returns (IGovPool.VotingRewards memory votingRewards, uint256 delegatorsRewards)
    {
        mapping(IGovPool.VoteType => IGovPool.RawVote) storage rawVotes = voteInfo.rawVotes;

        uint256 personalRewards = rawVotes[IGovPool.VoteType.PersonalVote].totalVoted;
        uint256 micropoolRewards = rawVotes[IGovPool.VoteType.MicropoolVote].totalVoted;
        uint256 treasuryRewards = rawVotes[IGovPool.VoteType.TreasuryVote].totalVoted;
        uint256 totalRawVoted = voteInfo.totalRawVoted;

        (uint256 micropoolPercentage, uint256 treasuryPercentage) = ICoreProperties(
            IGovPool(address(this)).coreProperties()
        ).getVoteRewardsPercentages();

        votingRewards.personal = _getMultipliedRewards(
            user,
            totalRewards.ratio(personalRewards, totalRawVoted)
        );
        votingRewards.micropool = totalRewards.ratio(micropoolRewards, totalRawVoted);
        votingRewards.treasury = totalRewards.ratio(treasuryRewards, totalRawVoted).percentage(
            treasuryPercentage
        );

        delegatorsRewards = votingRewards.micropool.percentage(
            PERCENTAGE_100 - micropoolPercentage
        );

        votingRewards.micropool -= delegatorsRewards;
    }

    function _recalculateReward(
        uint256 rewardsPaid,
        uint256 rewardsToPay
    ) private pure returns (uint256, uint256, uint256) {
        uint256 amountMin = rewardsPaid.min(rewardsToPay);

        return (rewardsPaid - amountMin, amountMin, rewardsToPay - amountMin);
    }

    function _recalculateAllRewards(
        uint256 rewardsPaid,
        uint256 staticRewardsToPay,
        IGovPool.VotingRewards memory votingRewardsPaid,
        IGovPool.VotingRewards memory votingRewardsToPay
    ) private pure returns (uint256, uint256) {
        uint256 staticRewardsPaid;

        (rewardsPaid, staticRewardsPaid, staticRewardsToPay) = _recalculateReward(
            rewardsPaid,
            staticRewardsToPay
        );

        (
            rewardsPaid,
            votingRewardsPaid.personal,
            votingRewardsToPay.personal
        ) = _recalculateReward(rewardsPaid, votingRewardsToPay.personal);
        (
            rewardsPaid,
            votingRewardsPaid.micropool,
            votingRewardsToPay.micropool
        ) = _recalculateReward(rewardsPaid, votingRewardsToPay.micropool);
        (
            rewardsPaid,
            votingRewardsPaid.treasury,
            votingRewardsToPay.treasury
        ) = _recalculateReward(rewardsPaid, votingRewardsToPay.treasury);

        return (staticRewardsToPay, staticRewardsPaid);
    }
}

contracts/libs/gov/gov-pool/GovPoolUnloc.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

import "../../../interfaces/gov/IGovPool.sol";
import "../../../interfaces/gov/user-keeper/IGovUserKeeper.sol";

library GovPoolUnlock {
    using Math for uint256;
    using EnumerableSet for EnumerableSet.UintSet;

    function unlockInProposals(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        address user
    ) external {
        EnumerableSet.UintSet storage userProposals = userInfos[user].votedInProposals;
        uint256[] memory proposalIds = userProposals.values();

        (, address userKeeperAddress, , , ) = IGovPool(address(this)).getHelperContracts();
        IGovUserKeeper userKeeper = IGovUserKeeper(userKeeperAddress);

        uint256 maxLockedAmount = userKeeper.maxLockedAmount(user);
        uint256 maxUnlocked;

        for (uint256 i; i < proposalIds.length; i++) {
            uint256 proposalId = proposalIds[i];

            if (_proposalIsActive(proposalId)) {
                continue;
            }

            IGovPool.RawVote storage personalRawVote = userInfos[user]
                .voteInfos[proposalId]
                .rawVotes[IGovPool.VoteType.PersonalVote];

            uint256 lockedInProposal = personalRawVote.tokensVoted;

            maxUnlocked = maxUnlocked.max(lockedInProposal);

            if (lockedInProposal != 0) {
                userKeeper.unlockTokens(proposalId, user);
            }

            if (personalRawVote.nftsVoted.length() != 0) {
                userKeeper.unlockNfts(personalRawVote.nftsVoted.values());
            }

            userProposals.remove(proposalId);
        }

        if (maxLockedAmount == maxUnlocked) {
            userKeeper.updateMaxTokenLockedAmount(userProposals.values(), user);
        }
    }

    function _proposalIsActive(uint256 proposalId) internal view returns (bool) {
        IGovPool.ProposalState state = IGovPool(address(this)).getProposalState(proposalId);

        return
            state != IGovPool.ProposalState.ExecutedFor &&
            state != IGovPool.ProposalState.ExecutedAgainst &&
            state != IGovPool.ProposalState.SucceededFor &&
            state != IGovPool.ProposalState.SucceededAgainst &&
            state != IGovPool.ProposalState.Defeated &&
            state != IGovPool.ProposalState.Locked;
    }
}

contracts/libs/gov/gov-pool/GovPoolView..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

import "@solarity/solidity-lib/libs/data-structures/memory/Vector.sol";

import "../../../interfaces/gov/user-keeper/IGovUserKeeper.sol";
import "../../../interfaces/gov/IGovPool.sol";
import "../../../interfaces/gov/validators/IGovValidators.sol";

import "../../../gov/GovPool.sol";

import "./GovPoolVote.sol";

import "../../../core/Globals.sol";

library GovPoolView {
    using EnumerableSet for EnumerableSet.UintSet;
    using GovPoolVote for IGovPool.ProposalCore;
    using Vector for Vector.UintVector;
    using Math for uint256;

    function getWithdrawableAssets(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        address user
    ) external view returns (uint256 withdrawableTokens, uint256[] memory withdrawableNfts) {
        (uint256[] memory unlockedIds, uint256[] memory lockedIds) = _getUserProposals(
            userInfos,
            user
        );

        uint256[] memory unlockedNfts = _getUnlockedNfts(
            userInfos,
            unlockedIds,
            user,
            IGovPool.VoteType.PersonalVote
        );

        (, address userKeeper, , , ) = IGovPool(address(this)).getHelperContracts();

        return IGovUserKeeper(userKeeper).getWithdrawableAssets(user, lockedIds, unlockedNfts);
    }

    function getProposals(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 offset,
        uint256 limit
    ) external view returns (IGovPool.ProposalView[] memory proposalViews) {
        GovPool govPool = GovPool(payable(address(this)));
        (, , address validatorsAddress, , ) = govPool.getHelperContracts();

        IGovValidators validators = IGovValidators(validatorsAddress);

        uint256 to = (offset + limit).min(govPool.latestProposalId()).max(offset);

        proposalViews = new IGovPool.ProposalView[](to - offset);

        for (uint256 i = offset; i < to; i++) {
            proposalViews[i - offset] = IGovPool.ProposalView({
                proposal: proposals[i + 1],
                validatorProposal: validators.getExternalProposal(i + 1),
                proposalState: govPool.getProposalState(i + 1),
                requiredQuorum: govPool.getProposalRequiredQuorum(i + 1),
                requiredValidatorsQuorum: validators.getProposalRequiredQuorum(i + 1, false)
            });
        }
    }

    function getProposalState(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        uint256 proposalId
    ) external view returns (IGovPool.ProposalState) {
        (, , address validators, , ) = IGovPool(address(this)).getHelperContracts();

        IGovPool.ProposalCore storage core = proposals[proposalId].core;

        uint64 voteEnd = core.voteEnd;

        if (voteEnd == 0) {
            return IGovPool.ProposalState.Undefined;
        }

        if (core.executed) {
            return
                _votesForMoreThanAgainst(core)
                    ? IGovPool.ProposalState.ExecutedFor
                    : IGovPool.ProposalState.ExecutedAgainst;
        }

        if (core.settings.earlyCompletion || voteEnd < block.timestamp) {
            if (core._quorumReachedThroughVoting()) {
                if (
                    !_votesForMoreThanAgainst(core) &&
                    proposals[proposalId].actionsOnAgainst.length == 0
                ) {
                    return IGovPool.ProposalState.Defeated;
                }

                if (core.settings.validatorsVote) {
                    return _getValidatorsExternalProposalState(proposalId, validators, core);
                }

                return _proposalStateBasedOnVoteResultsAndLock(core);
            }

            if (voteEnd < block.timestamp) {
                return IGovPool.ProposalState.Defeated;
            }
        }

        return IGovPool.ProposalState.Voting;
    }

    function _getValidatorsExternalProposalState(
        uint256 proposalId,
        address validators,
        IGovPool.ProposalCore storage core
    ) internal view returns (IGovPool.ProposalState) {
        IGovValidators.ProposalState status = IGovValidators(validators).getProposalState(
            proposalId,
            false
        );

        if (status == IGovValidators.ProposalState.Undefined) {
            if (IGovValidators(validators).validatorsCount() != 0) {
                return IGovPool.ProposalState.WaitingForVotingTransfer;
            }

            return _proposalStateBasedOnVoteResultsAndLock(core);
        }

        if (status == IGovValidators.ProposalState.Locked) {
            return IGovPool.ProposalState.Locked;
        }

        if (status == IGovValidators.ProposalState.Succeeded) {
            return _proposalStateBasedOnVoteResults(core);
        }

        if (status == IGovValidators.ProposalState.Defeated) {
            return IGovPool.ProposalState.Defeated;
        }

        return IGovPool.ProposalState.ValidatorVoting;
    }

    function _getUnlockedNfts(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        uint256[] memory unlockedIds,
        address user,
        IGovPool.VoteType voteType
    ) internal view returns (uint256[] memory unlockedNfts) {
        Vector.UintVector memory nfts = Vector.newUint();

        for (uint256 i; i < unlockedIds.length; i++) {
            IGovPool.RawVote storage votePower = userInfos[user]
                .voteInfos[unlockedIds[i]]
                .rawVotes[voteType];

            nfts.push(votePower.nftsVoted.values());
        }

        unlockedNfts = nfts.toArray();
    }

    function _getUserProposals(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        address user
    ) internal view returns (uint256[] memory unlockedIds, uint256[] memory lockedIds) {
        EnumerableSet.UintSet storage votes = userInfos[user].votedInProposals;
        uint256 proposalsLength = votes.length();

        Vector.UintVector memory unlocked = Vector.newUint();
        Vector.UintVector memory locked = Vector.newUint();

        for (uint256 i; i < proposalsLength; i++) {
            uint256 proposalId = votes.at(i);

            IGovPool.ProposalState state = IGovPool(address(this)).getProposalState(proposalId);

            if (
                state == IGovPool.ProposalState.ExecutedFor ||
                state == IGovPool.ProposalState.ExecutedAgainst ||
                state == IGovPool.ProposalState.SucceededFor ||
                state == IGovPool.ProposalState.SucceededAgainst ||
                state == IGovPool.ProposalState.Defeated
            ) {
                unlocked.push(proposalId);
            } else {
                locked.push(proposalId);
            }
        }

        unlockedIds = unlocked.toArray();
        lockedIds = locked.toArray();
    }

    function _votesForMoreThanAgainst(
        IGovPool.ProposalCore storage core
    ) internal view returns (bool) {
        return core.votesFor > core.votesAgainst;
    }

    function _proposalStateBasedOnVoteResultsAndLock(
        IGovPool.ProposalCore storage core
    ) internal view returns (IGovPool.ProposalState) {
        if (block.timestamp <= core.executeAfter) {
            return IGovPool.ProposalState.Locked;
        }

        return _proposalStateBasedOnVoteResults(core);
    }

    function _proposalStateBasedOnVoteResults(
        IGovPool.ProposalCore storage core
    ) internal view returns (IGovPool.ProposalState) {
        return
            _votesForMoreThanAgainst(core)
                ? IGovPool.ProposalState.SucceededFor
                : IGovPool.ProposalState.SucceededAgainst;
    }
}

contracts/libs/gov/gov-pool/GovPoolVote..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

import "@solarity/solidity-lib/libs/utils/TypeCaster.sol";

import "../../../interfaces/gov/IGovPool.sol";
import "../../../interfaces/gov/user-keeper/IGovUserKeeper.sol";
import "../../../interfaces/gov/voting/IVotePower.sol";

import "../../math/MathHelper.sol";

import "../../utils/TypeHelper.sol";

library GovPoolVote {
    using EnumerableSet for EnumerableSet.UintSet;
    using Math for uint256;
    using MathHelper for uint256;
    using TypeCaster for *;
    using TypeHelper for *;

    event VoteChanged(uint256 proposalId, address voter, bool isVoteFor, uint256 totalVoted);
    event QuorumReached(uint256 proposalId, uint256 timestamp);
    event QuorumUnreached(uint256 proposalId);

    function vote(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        mapping(address => IGovPool.UserInfo) storage userInfos,
        uint256 proposalId,
        uint256 amount,
        uint256[] calldata nftIds,
        bool isVoteFor
    ) external {
        IGovPool.ProposalCore storage core = proposals[proposalId].core;
        IGovPool.UserInfo storage userInfo = userInfos[msg.sender];
        IGovPool.VoteInfo storage voteInfo = userInfo.voteInfos[proposalId];

        IGovPool.VoteType voteType = core.settings.delegatedVotingAllowed
            ? IGovPool.VoteType.DelegatedVote
            : IGovPool.VoteType.PersonalVote;

        _canVote(userInfos, proposalId, amount, voteType);

        mapping(IGovPool.VoteType => IGovPool.RawVote) storage rawVotes = voteInfo.rawVotes;

        if (amount != 0 || nftIds.length != 0) {
            (, address userKeeperAddress, , , ) = IGovPool(address(this)).getHelperContracts();
            IGovUserKeeper userKeeper = IGovUserKeeper(userKeeperAddress);

            if (amount != 0) {
                userKeeper.lockTokens(proposalId, msg.sender, amount);
            }

            if (nftIds.length != 0) {
                userKeeper.lockNfts(msg.sender, voteType, nftIds);
            }

            _vote(rawVotes[IGovPool.VoteType.PersonalVote], amount, nftIds, msg.sender, voteType);
        }

        if (voteType != IGovPool.VoteType.DelegatedVote) {
            _voteDelegated(
                userInfos,
                rawVotes[IGovPool.VoteType.MicropoolVote],
                proposalId,
                msg.sender,
                IGovPool.VoteType.MicropoolVote
            );

            _voteDelegated(
                userInfos,
                rawVotes[IGovPool.VoteType.TreasuryVote],
                proposalId,
                msg.sender,
                IGovPool.VoteType.TreasuryVote
            );
        }

        _updateGlobalState(core, userInfos, proposalId, msg.sender, isVoteFor);

        require(
            voteInfo.totalRawVoted >= core.settings.minVotesForVoting,
            "Gov: low voting power"
        );
    }

    function revoteDelegated(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        mapping(address => IGovPool.UserInfo) storage userInfos,
        address voter,
        IGovPool.VoteType voteType
    ) external {
        IGovPool.UserInfo storage userInfo = userInfos[voter];

        uint256[] memory proposalIds = userInfo.votedInProposals.values();

        for (uint256 i = 0; i < proposalIds.length; i++) {
            uint256 proposalId = proposalIds[i];

            if (!_isVotingState(proposalId)) {
                continue;
            }

            IGovPool.ProposalCore storage core = proposals[proposalId].core;
            IGovPool.VoteInfo storage voteInfo = userInfo.voteInfos[proposalId];
            IGovPool.RawVote storage rawVote = voteInfo.rawVotes[voteType];

            if (core.settings.delegatedVotingAllowed) {
                continue;
            }

            _cancel(rawVote);
            _voteDelegated(userInfos, rawVote, proposalId, voter, voteType);

            _updateGlobalState(core, userInfos, proposalId, voter, voteInfo.isVoteFor);
        }
    }

    function cancelVote(
        mapping(uint256 => IGovPool.Proposal) storage proposals,
        mapping(address => IGovPool.UserInfo) storage userInfos,
        uint256 proposalId
    ) external {
        require(_isVotingState(proposalId), "Gov: cancel unavailable");

        IGovPool.ProposalCore storage core = proposals[proposalId].core;
        IGovPool.UserInfo storage userInfo = userInfos[msg.sender];
        IGovPool.VoteInfo storage voteInfo = userInfo.voteInfos[proposalId];

        mapping(IGovPool.VoteType => IGovPool.RawVote) storage rawVotes = voteInfo.rawVotes;
        IGovPool.RawVote storage personalRawVote = rawVotes[IGovPool.VoteType.PersonalVote];

        (, address userKeeperAddress, , , ) = IGovPool(address(this)).getHelperContracts();
        IGovUserKeeper userKeeper = IGovUserKeeper(userKeeperAddress);

        if (personalRawVote.tokensVoted != 0) {
            userKeeper.unlockTokens(proposalId, msg.sender);
        }

        if (personalRawVote.nftsVoted.length() != 0) {
            userKeeper.unlockNfts(personalRawVote.nftsVoted.values());
        }

        _cancel(rawVotes[IGovPool.VoteType.PersonalVote]);

        if (!core.settings.delegatedVotingAllowed) {
            _cancel(rawVotes[IGovPool.VoteType.MicropoolVote]);
            _cancel(rawVotes[IGovPool.VoteType.TreasuryVote]);
        }

        _updateGlobalState(core, userInfos, proposalId, msg.sender, voteInfo.isVoteFor);

        userKeeper.updateMaxTokenLockedAmount(userInfo.votedInProposals.values(), msg.sender);
    }

    function _voteDelegated(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        IGovPool.RawVote storage rawVote,
        uint256 proposalId,
        address voter,
        IGovPool.VoteType voteType
    ) internal {
        if (
            voteType == IGovPool.VoteType.TreasuryVote &&
            userInfos[voter].treasuryExemptProposals.contains(proposalId)
        ) {
            return;
        }

        (, address userKeeper, , , ) = IGovPool(address(this)).getHelperContracts();

        (uint256 amount, ) = IGovUserKeeper(userKeeper).tokenBalance(voter, voteType);

        _vote(rawVote, amount, new uint256[](0), voter, voteType);
    }

    function _vote(
        IGovPool.RawVote storage rawVote,
        uint256 amount,
        uint256[] memory nftIds,
        address voter,
        IGovPool.VoteType voteType
    ) internal {
        EnumerableSet.UintSet storage nftsVoted = rawVote.nftsVoted;

        for (uint256 i; i < nftIds.length; i++) {
            require(nftsVoted.add(nftIds[i]), "Gov: NFT already voted");
        }

        (, address userKeeperAddress, , , ) = IGovPool(address(this)).getHelperContracts();
        IGovUserKeeper userKeeper = IGovUserKeeper(userKeeperAddress);

        (uint256 nftsPower, ) = userKeeper.getTotalNftsPower(nftIds, voteType, voter, false);

        rawVote.tokensVoted = amount;
        rawVote.totalVoted = amount + nftsPower;

        if (
            voteType == IGovPool.VoteType.PersonalVote ||
            voteType == IGovPool.VoteType.DelegatedVote
        ) {
            rawVote.nftsAmount = nftIds.length;
        } else {
            (rawVote.nftsAmount, ) = userKeeper.nftBalance(voter, voteType);
        }
    }

    function _cancel(IGovPool.RawVote storage rawVote) internal {
        rawVote.tokensVoted = 0;
        rawVote.totalVoted = 0;
        rawVote.nftsAmount = 0;

        EnumerableSet.UintSet storage nftsVoted = rawVote.nftsVoted;

        while (nftsVoted.length() > 0) {
            nftsVoted.remove(nftsVoted.at(0));
        }
    }

    function _updateGlobalState(
        IGovPool.ProposalCore storage core,
        mapping(address => IGovPool.UserInfo) storage userInfos,
        uint256 proposalId,
        address voter,
        bool isVoteFor
    ) internal {
        IGovPool.UserInfo storage userInfo = userInfos[voter];

        IGovPool.VoteInfo storage voteInfo = userInfo.voteInfos[proposalId];
        EnumerableSet.UintSet storage activeVotes = userInfo.votedInProposals;

        if (_isVoted(voteInfo)) {
            _globalVote(
                core,
                voteInfo,
                activeVotes,
                userInfo.treasuryExemptProposals,
                proposalId,
                voter,
                isVoteFor
            );
        } else {
            _globalCancel(core, voteInfo, activeVotes, proposalId, isVoteFor);
        }

        if (_quorumReached(core)) {
            uint64 quorumTimestamp = core.settings.earlyCompletion
                ? uint64(block.timestamp)
                : core.voteEnd;

            core.executeAfter = core.settings.executionDelay + quorumTimestamp;

            emit QuorumReached(proposalId, uint256(quorumTimestamp));
        } else if (core.executeAfter != 0) {
            core.executeAfter = 0;

            emit QuorumUnreached(proposalId);
        }

        emit VoteChanged(proposalId, voter, isVoteFor, voteInfo.totalVoted);
    }

    function _globalVote(
        IGovPool.ProposalCore storage core,
        IGovPool.VoteInfo storage voteInfo,
        EnumerableSet.UintSet storage activeVotes,
        EnumerableSet.UintSet storage treasuryExemptProposals,
        uint256 proposalId,
        address voter,
        bool isVoteFor
    ) internal {
        activeVotes.add(proposalId);

        require(
            activeVotes.length() <= IGovPool(address(this)).coreProperties().getGovVotesLimit(),
            "Gov: vote limit reached"
        );

        mapping(IGovPool.VoteType => IGovPool.RawVote) storage rawVotes = voteInfo.rawVotes;

        uint256 totalRawVoted = rawVotes[IGovPool.VoteType.PersonalVote].totalVoted +
            rawVotes[IGovPool.VoteType.MicropoolVote].totalVoted +
            rawVotes[IGovPool.VoteType.TreasuryVote].totalVoted;
        uint256 totalVoted = _calculateVotes(
            treasuryExemptProposals,
            proposalId,
            voter,
            totalRawVoted
        );

        if (isVoteFor) {
            core.rawVotesFor = core.rawVotesFor - voteInfo.totalRawVoted + totalRawVoted;
            core.votesFor = core.votesFor - voteInfo.totalVoted + totalVoted;
        } else {
            core.rawVotesAgainst = core.rawVotesAgainst - voteInfo.totalRawVoted + totalRawVoted;
            core.votesAgainst = core.votesAgainst - voteInfo.totalVoted + totalVoted;
        }

        voteInfo.isVoteFor = isVoteFor;
        voteInfo.totalRawVoted = totalRawVoted;
        voteInfo.totalVoted = totalVoted;
    }

    function _globalCancel(
        IGovPool.ProposalCore storage core,
        IGovPool.VoteInfo storage voteInfo,
        EnumerableSet.UintSet storage activeVotes,
        uint256 proposalId,
        bool isVoteFor
    ) internal {
        require(activeVotes.remove(proposalId), "Gov: not active");

        if (isVoteFor) {
            core.rawVotesFor -= voteInfo.totalRawVoted;
            core.votesFor -= voteInfo.totalVoted;
        } else {
            core.rawVotesAgainst -= voteInfo.totalRawVoted;
            core.votesAgainst -= voteInfo.totalVoted;
        }

        voteInfo.isVoteFor = false;
        voteInfo.totalVoted = 0;
        voteInfo.totalRawVoted = 0;
    }

    function _canVote(
        mapping(address => IGovPool.UserInfo) storage userInfos,
        uint256 proposalId,
        uint256 amount,
        IGovPool.VoteType voteType
    ) internal view {
        IGovPool govPool = IGovPool(address(this));

        (, address userKeeper, , , ) = govPool.getHelperContracts();
        (uint256 tokenBalance, uint256 ownedBalance) = IGovUserKeeper(userKeeper).tokenBalance(
            msg.sender,
            voteType
        );

        IGovPool.UserInfo storage userInfo = userInfos[msg.sender];

        require(_isVotingState(proposalId), "Gov: vote unavailable");
        require(!_isVoted(userInfo.voteInfos[proposalId]), "Gov: need cancel");
        require(amount <= tokenBalance - ownedBalance, "Gov: wrong vote amount");
    }

    function _isVoted(IGovPool.VoteInfo storage voteInfo) internal view returns (bool) {
        mapping(IGovPool.VoteType => IGovPool.RawVote) storage rawVotes = voteInfo.rawVotes;

        IGovPool.RawVote storage personalRawVote = rawVotes[IGovPool.VoteType.PersonalVote];
        IGovPool.RawVote storage micropoolRawVote = rawVotes[IGovPool.VoteType.MicropoolVote];
        IGovPool.RawVote storage treasuryRawVote = rawVotes[IGovPool.VoteType.TreasuryVote];

        /// @dev nft power can be zero
        return
            personalRawVote.totalVoted != 0 ||
            micropoolRawVote.totalVoted != 0 ||
            treasuryRawVote.totalVoted != 0 ||
            personalRawVote.nftsAmount != 0 ||
            micropoolRawVote.nftsAmount != 0 ||
            treasuryRawVote.nftsAmount != 0;
    }

    function _quorumReached(IGovPool.ProposalCore storage core) internal view returns (bool) {
        (, address userKeeperAddress, , , ) = IGovPool(address(this)).getHelperContracts();

        uint256 totalPower = IGovUserKeeper(userKeeperAddress).getTotalPower();

        return
            PERCENTAGE_100.ratio(core.votesFor, totalPower) >= core.settings.quorum ||
            PERCENTAGE_100.ratio(core.votesAgainst, totalPower) >= core.settings.quorum;
    }

    function _quorumReachedThroughVoting(
        IGovPool.ProposalCore storage core
    ) internal view returns (bool) {
        return core.executeAfter != 0;
    }

    function _calculateVotes(
        EnumerableSet.UintSet storage treasuryExemptProposals,
        uint256 proposalId,
        address voter,
        uint256 voteAmount
    ) internal view returns (uint256) {
        (, address userKeeper, , , address votePower) = IGovPool(address(this))
            .getHelperContracts();

        IGovUserKeeper.VotingPowerView[] memory votingPowers = IGovUserKeeper(userKeeper)
            .votingPower(
                [voter, voter, voter].asDynamic(),
                [
                    IGovPool.VoteType.PersonalVote,
                    IGovPool.VoteType.MicropoolVote,
                    IGovPool.VoteType.TreasuryVote
                ].asDynamic(),
                false
            );

        return
            IVotePower(votePower).transformVotesFull(
                voter,
                voteAmount,
                votingPowers[0].rawPower,
                votingPowers[1].rawPower,
                treasuryExemptProposals.contains(proposalId) ? 0 : votingPowers[2].rawPower
            );
    }

    function _isVotingState(uint256 proposalId) internal view returns (bool) {
        return
            IGovPool(address(this)).getProposalState(proposalId) == IGovPool.ProposalState.Voting;
    }
}

